162		if err != nil {
163			return nil, err
164		}
165		defer rows.Close()
166	
167		list := make([]*store.Memo, 0)
168		for rows.Next() {
169			var memo store.Memo
170			var payloadBytes []byte
171			dests := []any{
172				&memo.ID,
173				&memo.UID,
174				&memo.CreatorID,
175				&memo.CreatedTs,
176				&memo.UpdatedTs,
177				&memo.RowStatus,
178				&memo.Visibility,
